BEGIN;

SET search_path=talentra,public;

CREATE TABLE "integration_source" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "account_id" bigint NOT NULL,
  "code" varchar(80) NOT NULL,
  "owner_role" varchar(150) NOT NULL,
  "endpoint_reference" varchar(255) NOT NULL,
  "secret_reference" varchar(255) NOT NULL,
  "enabled" boolean DEFAULT false NOT NULL,
  "max_inflight" integer NOT NULL,
  "timeout_ms" integer NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  CONSTRAINT "uq_integration_source_1" UNIQUE ("account_id", "code"),
  CONSTRAINT "uq_integration_source_2" UNIQUE ("id", "account_id"),
  CONSTRAINT "ck_integration_source_1" CHECK (max_inflight > 0),
  CONSTRAINT "ck_integration_source_2" CHECK (timeout_ms > 0)
);

CREATE TABLE "integration_contract" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "account_id" bigint NOT NULL,
  "integration_source_id" bigint NOT NULL,
  "contract_key" varchar(150) NOT NULL,
  "schema_version" integer NOT NULL,
  "direction_reference_value_id" bigint NOT NULL,
  "schema_sha256" char(64) NOT NULL,
  "max_payload_bytes" integer NOT NULL,
  "effective_at" timestamptz NOT NULL,
  "retired_at" timestamptz,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  CONSTRAINT "uq_integration_contract_1" UNIQUE ("account_id", "integration_source_id", "contract_key", "schema_version"),
  CONSTRAINT "uq_integration_contract_2" UNIQUE ("id", "account_id"),
  CONSTRAINT "ck_integration_contract_1" CHECK (schema_version > 0),
  CONSTRAINT "ck_integration_contract_2" CHECK (max_payload_bytes > 0),
  CONSTRAINT "ck_integration_contract_3" CHECK (retired_at IS NULL OR retired_at > effective_at)
);

CREATE TABLE "external_reference" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "account_id" bigint NOT NULL,
  "integration_source_id" bigint NOT NULL,
  "external_key" varchar(255) NOT NULL,
  "candidate_profile_id" bigint,
  "job_requirement_id" bigint,
  "gig_assignment_id" bigint,
  "payment_order_id" bigint,
  "organisation_id" bigint,
  "notification_delivery_id" bigint,
  "city_id" bigint,
  "source_version" bigint NOT NULL,
  "last_seen_at" timestamptz NOT NULL,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  CONSTRAINT "uq_external_reference_1" UNIQUE ("account_id", "integration_source_id", "external_key"),
  CONSTRAINT "uq_external_reference_2" UNIQUE ("id", "account_id"),
  CONSTRAINT "ck_external_reference_1" CHECK (source_version >= 0),
  CONSTRAINT "ck_external_reference_2" CHECK ((CASE WHEN candidate_profile_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN job_requirement_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN gig_assignment_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN payment_order_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN organisation_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN notification_delivery_id IS NOT NULL THEN 1 ELSE 0 END + CASE WHEN city_id IS NOT NULL THEN 1 ELSE 0 END) = 1)
);

CREATE TABLE "integration_inbox" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "account_id" bigint NOT NULL,
  "integration_contract_id" bigint NOT NULL,
  "event_key" varchar(150) NOT NULL,
  "correlation_key" varchar(150) NOT NULL,
  "payload_sha256" char(64) NOT NULL,
  "payload_reference" varchar(255) NOT NULL,
  "source_version" bigint NOT NULL,
  "occurred_at" timestamptz NOT NULL,
  "received_at" timestamptz NOT NULL,
  "status_reference_value_id" bigint NOT NULL,
  "attempt_count" integer DEFAULT 0 NOT NULL,
  "next_attempt_at" timestamptz NOT NULL,
  "lease_token" varchar(150),
  "lease_expires_at" timestamptz,
  "processed_at" timestamptz,
  "last_error_code" varchar(80),
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  CONSTRAINT "uq_integration_inbox_1" UNIQUE ("account_id", "integration_contract_id", "event_key"),
  CONSTRAINT "uq_integration_inbox_2" UNIQUE ("id", "account_id"),
  CONSTRAINT "ck_integration_inbox_1" CHECK (source_version >= 0),
  CONSTRAINT "ck_integration_inbox_2" CHECK (attempt_count >= 0),
  CONSTRAINT "ck_integration_inbox_3" CHECK ((lease_token IS NULL) = (lease_expires_at IS NULL))
);

CREATE TABLE "delivery_attempt" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "account_id" bigint NOT NULL,
  "integration_inbox_id" bigint,
  "outbox_event_id" bigint,
  "attempt_number" integer NOT NULL,
  "started_at" timestamptz NOT NULL,
  "finished_at" timestamptz NOT NULL,
  "http_status" integer,
  "outcome_reference_value_id" bigint NOT NULL,
  "error_code" varchar(80),
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  CONSTRAINT "uq_delivery_attempt_1" UNIQUE ("integration_inbox_id", "attempt_number"),
  CONSTRAINT "uq_delivery_attempt_2" UNIQUE ("outbox_event_id", "attempt_number"),
  CONSTRAINT "ck_delivery_attempt_1" CHECK (attempt_number > 0),
  CONSTRAINT "ck_delivery_attempt_2" CHECK (finished_at >= started_at),
  CONSTRAINT "ck_delivery_attempt_3" CHECK (http_status IS NULL OR http_status BETWEEN 100 AND 599),
  CONSTRAINT "ck_delivery_attempt_4" CHECK ((integration_inbox_id IS NOT NULL) <> (outbox_event_id IS NOT NULL))
);

CREATE TABLE "reconciliation_run" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "account_id" bigint NOT NULL,
  "integration_source_id" bigint NOT NULL,
  "window_start" timestamptz NOT NULL,
  "window_end" timestamptz NOT NULL,
  "source_count" bigint NOT NULL,
  "applied_count" bigint NOT NULL,
  "rejected_count" bigint NOT NULL,
  "duplicate_count" bigint NOT NULL,
  "pending_count" bigint NOT NULL,
  "completed_at" timestamptz,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  CONSTRAINT "uq_reconciliation_run_1" UNIQUE ("account_id", "integration_source_id", "window_start", "window_end"),
  CONSTRAINT "uq_reconciliation_run_2" UNIQUE ("id", "account_id"),
  CONSTRAINT "ck_reconciliation_run_1" CHECK (window_end > window_start),
  CONSTRAINT "ck_reconciliation_run_2" CHECK (source_count >= 0 AND applied_count >= 0 AND rejected_count >= 0 AND duplicate_count >= 0 AND pending_count >= 0),
  CONSTRAINT "ck_reconciliation_run_3" CHECK (source_count = applied_count + rejected_count + duplicate_count + pending_count),
  CONSTRAINT "ck_reconciliation_run_4" CHECK (completed_at IS NULL OR pending_count = 0)
);

CREATE TABLE "integration_rejection" (
  "id" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY NOT NULL,
  "account_id" bigint NOT NULL,
  "integration_inbox_id" bigint NOT NULL,
  "reason_code" varchar(80) NOT NULL,
  "field_path" varchar(255) NOT NULL,
  "replay_authorized_by" bigint,
  "resolved_at" timestamptz,
  "created_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "created_by" bigint,
  "updated_at" timestamptz DEFAULT CURRENT_TIMESTAMP NOT NULL,
  "updated_by" bigint,
  CONSTRAINT "ck_integration_rejection_1" CHECK (resolved_at IS NULL OR replay_authorized_by IS NOT NULL)
);

CREATE TABLE "candidate_verification" (
